#!/usr/bin/env python3
"""Review (do not promote) the strict 2009 source-only concordance cohort."""
import csv,json,math
from datetime import datetime,timezone
from pathlib import Path
R=Path(__file__).resolve().parents[1]
rows=json.loads((R/'data/source-only-pilot-2009-strong-copy-concordance.json').read_text());rows.sort(key=lambda x:x['dateTime'])
def utc(t):return datetime.fromtimestamp(t,timezone.utc).isoformat().replace('+00:00','Z')
def eq(a,b):return sum(r[a]==r[b] for r in rows)
blocks=[];cur=[]
for r in rows:
 if cur and r['dateTime']==cur[-1]['dateTime']+300:cur.append(r)
 else:
  if cur:blocks.append(cur)
  cur=[r]
if cur:blocks.append(cur)
neighbor=[]
for r in rows:neighbor.extend(abs(r[k]-r['old_temp']) for k in ('prev_temp','next_temp') if r[k] is not None)
summary={'scope':'100 strict source-only timestamps in UTC 2009; candidate screen only','classification_counts':{'RESTORED':0,'ESTIMATED':0,'REVIEW_REQUIRED':100,'MISSING':0},'source_rows':{'old_weewx':100,'weewx_WH1080':100,'pocasi-loucka.eu_old':100},'reconstruction_target_rows':0,'target_change_events_all_variables':0,'basis':'The previously completed exhaustive indexed source-only history audit found zero reconstruction_changes events across all 207,182 timestamps; no new event rows were created.','source_units':{'old_weewx':sorted({r['old_units'] for r in rows}),'weewx_WH1080':sorted({r['wh_units'] for r in rows}),'pocasi-loucka.eu_old':sorted({r['old_site_units'] for r in rows})},'source_intervals_minutes':{'old_weewx':sorted({r['old_interval'] for r in rows}),'weewx_WH1080':sorted({r['wh_interval'] for r in rows})},'all_primary_fields_nonnull_in_both_source_copies':True,'five_primary_exact_copy_matches':{'outTemp':100,'outHumidity':100,'rain':100,'rainRate':100,'windSpeed':100},'exact_site_old_value_matches':{'outTemp':eq('old_temp','site_temp'),'outHumidity':eq('old_rh','site_rh'),'rain':eq('old_rain','site_rain'),'rainRate':eq('old_rainrate','site_rainrate'),'windSpeed':eq('old_wind','site_wind')},'source_value_ranges':{k:{'min':min(r[k] for r in rows if r[k] is not None),'max':max(r[k] for r in rows if r[k] is not None)} for k in ('old_temp','old_rh','old_rain','old_rainrate','old_wind')},'zero_outTemp_count':sum(r['old_temp']==0 for r in rows),'neighbor_temperature_delta_c':{'n':len(neighbor),'max':round(max(neighbor),3),'p95_empirical':sorted(neighbor)[math.ceil(.95*len(neighbor))-1],'count_gt_2c':sum(x>2 for x in neighbor),'count_gt_5c':sum(x>5 for x in neighbor)},'exact_300s_blocks':[{'n':len(b),'start_utc':utc(b[0]['dateTime']),'end_utc':utc(b[-1]['dateTime']),'distinct':{k:len({r[k] for r in b}) for k in ('old_temp','old_rh','old_rain','old_rainrate','old_wind')}} for b in blocks],'exclusion_reasons':['Two long 300-second runs of constant source values (14 and 86 points) are suspicious; copies may share the same source event.','One 2009-04-04 10:35Z target has a 9.48 C difference from the prior 5-minute source value.','Third archive has exact-time rows but rain differs in all 100 cases; rainRate differs in one; do not use it as universal corroboration.','usUnits differs in third archive (16 vs 17); the standard unit code distinction does not authenticate the historical export conversion.','Export archive role, physical source identity, calibration/driver epoch and timestamp semantics remain unauthenticated.'],'decision':'REVIEW_REQUIRED; no correction proposal or batch operation emitted','protected_scope':'2009 only; Q1 2018 not queried; 2021 not queried'}
(R/'data/source_only_pilot_2009_strong_copy_concordance_summary.json').write_text(json.dumps(summary,indent=2,ensure_ascii=False)+'\n')
fields=['dateTime','old_units','wh_units','old_site_units','old_interval','wh_interval','old_temp','old_rh','old_rain','old_rainrate','old_wind','site_temp','site_rh','site_rain','site_rainrate','site_wind','prev_time','prev_temp','prev_rh','next_time','next_temp','next_rh']
with (R/'reports/2026-11-13-source-only-pilot-2009-row-evidence.csv').open('w',newline='') as f:
 w=csv.DictWriter(f,fieldnames=fields+['dateTime_utc','classification','reason_codes']);w.writeheader()
 for r in rows:
  q={k:r[k] for k in fields};q['dateTime_utc']=utc(r['dateTime']);q['classification']='REVIEW_REQUIRED'
  reasons=['SOURCE_LINEAGE_UNAUTHENTICATED','SITE_RAIN_DISCORDANCE']
  if r['dateTime'] in {x['dateTime'] for b in blocks if len(b)>1 for x in b}:reasons.append('LONG_CONSTANT_RUN')
  if any(abs(r[k]-r['old_temp'])>2 for k in ('prev_temp','next_temp') if r[k] is not None):reasons.append('NEIGHBOR_TEMPERATURE_JUMP')
  q['reason_codes']=';'.join(reasons);w.writerow(q)
lines=['# Zdrojově nejkonkordantnější source-only kohorta 2009 — stále REVIEW_REQUIRED','', '**Rozsah:** 100 cílových timestampů v roce 2009. Cílený výběr vyžaduje oba WeeWX archivy, přesnou přítomnost také v `pocasi-loucka.eu_old`, `interval=5`, přesný UTC 300s grid, `usUnits=17`, všech pět primárních veličin non-NULL a přesně shodných mezi dvěma WeeWX kopiemi, a absenci přesného target row v reconstruction archive.','', '## Výsledek rozhodovacího screeningu','', '**RESTORED 0 / ESTIMATED 0 / REVIEW_REQUIRED 100 / MISSING 0.** Žádná korekce nebyla vytvořena. Tato kohorta je pouze nejlépe shodná agregátní skupina vhodná k cílenému ověření provenance; nesplňuje důkaz identity zdrojového archivu.','', '| Kontrola | Výsledek |','|---|---:|','| Timestampy / source rows | 100 / 300 ve třech archivech |','| Rekonstrukční target row | 0 |','| Změnová historie | 0 podle již ověřené úplné source-only event kontroly |','| WeeWX `usUnits` / interval | 17 / 5 min, oba zdroje |','| site-old `usUnits` | 16 ve všech 100 |','| Obě WeeWX kopie: přesná shoda pěti primárních fields | 100/100 pro každý field |','| site-old shoda outTemp / RH / rain / rainRate / windSpeed | 100 / 100 / 0 / 99 / 100 |','| outTemp nula | 0 |','| outTemp rozsah / RH rozsah | 4.8–22.2 °C / 62–90 % |','| neighbor ΔT >2 °C / >5 °C | 1 / 1; maximum 9.48 °C |','| Souvislé source runs na 300s | 14 a 86 bodů; čtyři hodnoty zůstávají konstantní v obou, ve druhém bloku všech pět |','', '## Proč ani tato skupina není RESTORED','', 'Zdrojové kopie souhlasí. V obou blocích zůstávají outTemp, RH, rainRate a vítr konstantní; v prvním se rain liší u jednoho z 14 bodů. Druhý blok je konstantní ve všech pěti polích. Délky jsou 70 minut a 7 h 5 min. U druhého bloku je `rain=48` v každém z 86 řádků, zatímco `pocasi-loucka.eu_old` má v 85 z 86 bodů `rain=0`; první blok má v site-old také `rain=0` navzdory zdrojovým hodnotám 2.4–6. `rainRate` má jeden rozdíl. Jeden cíl má také extrémní 9.48 °C pětiminutový skok na levém sousedovi. Kopie mohou sdílet tentýž sensor/export defect; jejich počet není nezávislé potvrzení.','', 'WeeWX dokumentuje `usUnits=16` jako METRIC (rain cm, wind km/h) a `17` jako METRICWX (rain mm, wind m/s); standardní kódy pomáhají interpretovat jednotky, ale nejsou důkazem, jak historický export skutečně zapsal každé pole. Tím spíše nelze přenést hodnoty `pocasi-loucka.eu_old` bez per-variable provenance. [WeeWX unit documentation](https://www.weewx.com/docs/customizing.htm).','', '## Požadovaný důkaz pro opětovné zvážení','', '1. Export manifest nebo původní DB backup s ověřitelnou vazbou obou WeeWX archivů na historickou stanici/driver a účinné datum konfigurace v roce 2009.','2. Originální senzorové/driver logy nebo independent local backup pro 2009-04-04 10:35Z a 2009-08-12 05:50–12:55Z, které vyřeší teplotní skok a konstantní hodnotové série.','3. Kanálově specifický popis `rain`, `rainRate` a jednotek pro `pocasi-loucka.eu_old` (`usUnits=16`) v těchto dvou epizodách; bez něj ponechat tyto veličiny conflicted.','4. Per-variable obnovu posuzovat zvlášť; případná validace outTemp/RH/wind nesmí odemknout rain/rainRate.','', '## Reprodukovatelnost a bezpečnost','', 'Kandidátní cohort SQL: `sql/readonly/source_only_pilot_2009_strict_copy_cohort.sql`; lokální skript: `scripts/analyze_source_only_pilot_2009.py`; row-level evidence: `reports/2026-11-13-source-only-pilot-2009-row-evidence.csv`; agregát: `data/source_only_pilot_2009_strong_copy_concordance_summary.json`. SELECT only; žádné zápisy, staging, změny Q1 2018/2021 ani publikace.']
(R/'reports/2026-11-13-source-only-pilot-2009-strong-concordance.md').write_text('\n'.join(lines)+'\n')
print(json.dumps({'restored':0,'estimated':0,'review_required':100,'missing':0,'blocks':summary['exact_300s_blocks'],'site_matches':summary['exact_site_old_value_matches'],'max_neighbor_delta':summary['neighbor_temperature_delta_c']['max']}))
